       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "tipoCuenta",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "valor",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "referencia",
       "type": "text(var,40,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "int",
     "legacy_output": "@o_secuencial"
    }
   ]
