 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Validates the account type, the order and the funds, computes the tariff, commission and total, debits the account (and the commission separately when applicable), marks the order as paid and commits atomically.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013"
   ],
   "inputs": [
    {
     "name": "orden",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "empresa",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "servicio",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "tipoCuenta",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "cuenta",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "valor",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "canal",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "fechaProceso",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movimiento",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "mensaje",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "50001",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "50002",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "50003",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "50004",
     "message": "FONDOS INSUFICIENTES"
    },
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "OrderRepository",
    "CompanyTariffRepository",
    "ServiceRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/pay",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Data and debit procedure stay in the legacy databases",
   "context": "The order, tariff, service and account tables live in db_pagos, db_admin and db_cuentas, and the debit is done by db_cuentas..sp_debito, which other systems also use.",
   "decision": "Use data_strategy same_database: the target uses the legacy driver and qualified table names, and calls sp_debito through the generated DebitGateway adapter. The debit logic is not reimplemented.",
   "consequences": "No data migration. The service depends on the legacy databases and on sp_debito keeping its contract."
  },
  {
   "title": "Single transaction from the first debit to the order update",
   "context": "The legacy opens the transaction at line 108 after all validations, and rolls back at three points (lines 119, 136, 155), committing at line 161.",
   "decision": "The PayOrder use case is one unit of work: validations and calculations run before it begins, and the debit, optional commission debit and order update run inside. Any failure rolls back everything and rejects with the matching error code: DEBIT_FAILED, COMMISSION_FAILED or ORDER_UPDATE_FAILED. There are no savepoints.",
   "consequences": "A debit is never kept if the commission or the order update fails. Rejections before the transaction do not roll back anything because nothing has been written yet."
  },
  {
   "title": "Failure of sp_debito mapped by the gateway",
   "context": "The legacy treats a non-zero return code of sp_debito (or @@error) as a failure, and reads the movement sequence from the output parameter @o_secuencial.",
   "decision": "DebitGateway.debit returns the movement sequence and raises a failure when sp_debito returns non-zero. The use case maps that failure to DEBIT_FAILED for the order debit and to COMMISSION_FAILED for the separate commission debit. The commission call ignores the returned sequence.",
   "consequences": "Return-code plumbing is not translated. Exceptions replace it."
  },
  {
   "title": "Validation order and early rejection preserved",
   "context": "The legacy evaluates account type, order existence, order status, tariff, commission, total and funds in that order, and the first failing check wins.",
   "decision": "The use case keeps the same order of checks, so the same error is produced for the same input.",
   "consequences": "Error precedence is identical to the legacy."
  },
  {
   "title": "Monetary arithmetic and rounding",
   "context": "The legacy computes with money (4 decimals) and uses round(@w_tarifa / 2, 2) for the WEB channel.",
   "decision": "Use BigDecimal with scale 4 for amounts. The WEB commission is the tariff divided by 2 and rounded to 2 decimals with HALF_UP, then stored with scale 4. A NULL tariff becomes 0, and the NOMINA service always yields commission 0.",
   "consequences": "Results match the legacy for amounts with up to 4 decimals. The separate-charge flag is 'N' when the tariff comes from the service default."
  },
  {
   "title": "Missing account row behaves as in the legacy",
   "context": "If the balance lookup returns no row, @w_saldo stays NULL and the funds comparison is not true, so the legacy does not reject with 50004 and goes on to the debit.",
   "decision": "An empty result from AccountRepository is treated as an unknown balance: the funds check does not reject, and the debit is attempted, where sp_debito decides.",
   "consequences": "This legacy behaviour is kept on purpose. The reviewer may decide to reject unknown accounts in a later change."
  },
  {
   "title": "Channel default and error logging",
   "context": "@i_canal defaults to 'WEB' in the legacy, and errors are logged through cobis..sp_cerror.",
   "decision": "If the channel is not provided, the use case uses 'WEB'. cobis..sp_cerror is infrastructure and is not translated: the error code and message are returned by the HTTP layer and logged by the framework.",
   "consequences": "No call to sp_cerror from the new service."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "same_database"
}

Use case: PayOrder

Rules:
[
 {
  "id": "RULE-001",
  "name": "Account type must be CTE, AHO or VIR",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order is only accepted for account types CTE, AHO or VIR. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is allowed\n  Given the account type is 'AHO'\n  When the payment order is validated\n  Then no error is set for the account type",
   "Scenario: Account type is not allowed\n  Given the account type is 'PRE'\n  When the payment order is validated\n  Then the error code is 50001\n  And the message is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Payment order must be pending to be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "An order can only proceed when its status is 'P' (pending). Any other status is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "The status ord_estado of the order identified by @i_orden and @i_empresa in db_pagos..pg_orden is not 'P'.",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'. The slice does not show what happens after the error is set.",
  "inputs": [
   {
    "name": "@i_orden",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order is pending\n  Given order 100 of company 1 has status 'P'\n  When the payment procedure checks the order\n  Then no error is raised by this check",
   "Scenario: Order is not pending\n  Given order 100 of company 1 has status 'X'\n  When the payment procedure checks the order\n  Then @w_error is 50003\n  And @o_mensaje is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 54
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 56,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment rejected when order does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "If the lookup of the order to be paid returns no rows, the payment is rejected with error code 50002 and the message 'ORDEN NO EXISTE'.",
  "condition": "@@rowcount = 0 after the preceding order lookup",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the lookup of the order to pay returns 0 rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the lookup of the order to pay returns 1 row\n  When the payment procedure evaluates the result\n  Then error 50002 is not set by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Commission tariff lookup: company-specific tariff overrides service default",
  "category": "calculation",
  "priority": "P0",
  "statement": "The base tariff for a payment is the one agreed for the company and service. If the company has no specific tariff for that service, the service's default tariff is used and the commission is not charged separately ('N'). If no tariff can be determined, it is zero.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise use ad_servicio.srv_codigo = @i_servicio; if the resulting tariff is NULL.",
  "action": "With a company row: tariff = tar_valor and separate-charge flag = tar_separada. Without one (@@rowcount = 0): tariff = srv_tarifa and flag = 'N'. If the tariff is NULL it becomes 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company tariff exists\nGiven company 10 has a tariff of 2.0000 with separate charge 'S' for service 'LUZ'\nWhen the tariff is resolved\nThen the tariff is 2.0000 and the separate-charge flag is 'S'",
   "Scenario: Fall back to service tariff\nGiven company 10 has no tariff row for service 'AGUA' and the service tariff is 1.5000\nWhen the tariff is resolved\nThen the tariff is 1.5000 and the separate-charge flag is 'N'",
   "Scenario: No tariff defined\nGiven the resolved tariff is NULL\nWhen the tariff is resolved\nThen the tariff is 0"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 62,
    "line_end": 66
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 68,
    "line_end": 68
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 70,
    "line_end": 72
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 76,
    "line_end": 77
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Comisión por canal y servicio NOMINA",
  "category": "calculation",
  "priority": "P0",
